#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(a: P3, b: P3, c: P3, f: P3, r: i128) -> Option<Sign> {
    let d_x = exact_f64(b.x) - exact_f64(a.x);
    let d_y = exact_f64(b.y) - exact_f64(a.y);
    let d_z = exact_f64(b.z) - exact_f64(a.z);
    let e_x = exact_f64(f.x) - exact_f64(c.x);
    let e_y = exact_f64(f.y) - exact_f64(c.y);
    let e_z = exact_f64(f.z) - exact_f64(c.z);
    let w_x = exact_f64(a.x) - exact_f64(c.x);
    let w_y = exact_f64(a.y) - exact_f64(c.y);
    let w_z = exact_f64(a.z) - exact_f64(c.z);
    let n_x_1 = d_y * e_z;
    let n_x_2 = d_z * e_y;
    let n_x = n_x_1 - n_x_2;
    let n_y_1 = d_z * e_x;
    let n_y_2 = d_x * e_z;
    let n_y = n_y_1 - n_y_2;
    let n_z_1 = d_x * e_y;
    let n_z_2 = d_y * e_x;
    let n_z = n_z_1 - n_z_2;
    let nn_1 = n_x * n_x;
    let nn_2 = n_y * n_y;
    let nn_3 = nn_1 + nn_2;
    let nn_4 = n_z * n_z;
    let nn = nn_3 + nn_4;
    let det_1 = n_x * w_x;
    let det_2 = n_y * w_y;
    let det_3 = det_1 + det_2;
    let det_4 = n_z * w_z;
    let det = det_3 + det_4;
    let r = rounded_f64(r, 41)?;
    let delta_1 = r * r;
    let delta_2 = delta_1 * nn;
    let delta_3 = det * det;
    let delta = delta_2 - delta_3;
    let m_x = largest_magnitude([d_x, e_x, w_x]);
    let m_y = largest_magnitude([d_y, e_y, w_y]);
    let m_z = largest_magnitude([d_z, e_z, w_z]);
    let m_r = largest_magnitude([r]);
    let scale = m_y * m_y * m_z * m_z * m_r * m_r;
    let scale = larger(scale, m_x * m_x * m_z * m_z * m_r * m_r);
    let scale = larger(scale, m_x * m_x * m_y * m_y * m_r * m_r);
    let scale = larger(scale, m_x * m_x * m_y * m_y * m_z * m_z);
    decide(delta, ERROR, scale)
}

/// `line_cylinder`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out; `None` also for a
/// rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(a: P3, b: P3, c: P3, f: P3, r: i128) -> Option<I256> {
    let d_x = b.x.get().checked_sub(a.x.get())?;
    let d_y = b.y.get().checked_sub(a.y.get())?;
    let d_z = b.z.get().checked_sub(a.z.get())?;
    let e_x = f.x.get().checked_sub(c.x.get())?;
    let e_y = f.y.get().checked_sub(c.y.get())?;
    let e_z = f.z.get().checked_sub(c.z.get())?;
    let w_x = a.x.get().checked_sub(c.x.get())?;
    let w_y = a.y.get().checked_sub(c.y.get())?;
    let w_z = a.z.get().checked_sub(c.z.get())?;
    let n_x_1 = i128::from(d_y).checked_mul(i128::from(e_z))?;
    let n_x_2 = i128::from(d_z).checked_mul(i128::from(e_y))?;
    let n_x = n_x_1.checked_sub(n_x_2)?;
    let n_y_1 = i128::from(d_z).checked_mul(i128::from(e_x))?;
    let n_y_2 = i128::from(d_x).checked_mul(i128::from(e_z))?;
    let n_y = n_y_1.checked_sub(n_y_2)?;
    let n_z_1 = i128::from(d_x).checked_mul(i128::from(e_y))?;
    let n_z_2 = i128::from(d_y).checked_mul(i128::from(e_x))?;
    let n_z = n_z_1.checked_sub(n_z_2)?;
    let nn_1 = I256::product_i128(n_x, n_x)?;
    let nn_2 = I256::product_i128(n_y, n_y)?;
    let nn_3 = nn_1.checked_add(&nn_2)?;
    let nn_4 = I256::product_i128(n_z, n_z)?;
    let nn = nn_3.checked_add(&nn_4)?;
    let det_1 = n_x.checked_mul(i128::from(w_x))?;
    let det_2 = n_y.checked_mul(i128::from(w_y))?;
    let det_3 = det_1.checked_add(det_2)?;
    let det_4 = n_z.checked_mul(i128::from(w_z))?;
    let det = det_3.checked_add(det_4)?;
    let r = i64::try_from(within(r, 41)?).ok()?;
    let delta_1 = i128::from(r).checked_mul(i128::from(r))?;
    let delta_2 = nn.checked_mul_i128(delta_1)?;
    let delta_3 = I256::product_i128(det, det)?;
    let delta = delta_2.checked_sub(&delta_3)?;
    Some(delta)
}

/// `line_cylinder`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    reason = "one-letter names are the description's points"
)]
pub fn exact(a: P3, b: P3, c: P3, f: P3, r: i128) -> Option<Sign> {
    value(a, b, c, f, r).map(|v| v.signum())
}
